def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "announce_alert": And([
            Not(self.thermos_moved_aside),
            Not(self.tray_placed),
            self.detection_insufficiently_grounded,
            self.robot_has_detection_capability
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
